export function normalizeFileInput(e){if(e instanceof Uint8Array)return{size:e.byteLength,uploadBody:e,getBytes:async()=>e};if(e instanceof ArrayBuffer){const r=new Uint8Array(e);return{size:r.byteLength,uploadBody:r,getBytes:async()=>r}}if("undefined"!=typeof Blob&&e instanceof Blob){let r;return{size:e.size,uploadBody:e,getBytes:async()=>(r||(r=new Uint8Array(await e.arrayBuffer())),r)}}throw new TypeError("Unsupported file input: expected Uint8Array, ArrayBuffer, Blob, or File")}